<script setup lang="ts">
import {computed,ref,watch} from 'vue';
type Talent={id:number;name:string;level:number;charId:number;sect:number;supported?:boolean;description:string;isBattleTalent?:boolean;supportReason?:string};
const props=defineProps<{modelValue:number[];characterId:number;characters:{id:number;sect:number;talents:number[]}[];talents:Talent[]}>();
const emit=defineEmits<{'update:modelValue':[ids:number[]]}>();
const names=['炼气','筑基','金丹','元婴','化神'];const opened=ref(0),search=ref('');
const character=computed(()=>props.characters.find(c=>c.id===props.characterId));
const initial=computed(()=>props.talents.find(t=>t.level===1&&character.value?.talents.includes(t.id)));
const slots=computed(()=>names.map((_,i)=>i===0?initial.value:props.talents.find(t=>t.level===i+1&&props.modelValue.includes(t.id))));
const candidates=computed(()=>props.talents.filter(t=>t.level===opened.value&&!(props.characterId===1000005&&[93,94,95,96].includes(t.id))&&(!t.charId||t.charId===props.characterId)&&(!t.sect||!character.value||t.sect===character.value.sect)&&(!search.value||t.name.includes(search.value)||String(t.id).includes(search.value))));
watch(()=>props.characterId,()=>{const ids=props.modelValue.filter(id=>{const t=props.talents.find(t=>t.id===id);return t&&t.level!==1&&(!t.charId||t.charId===props.characterId)&&(!t.sect||!character.value||t.sect===character.value.sect)});if(initial.value)ids.unshift(initial.value.id);if(JSON.stringify(ids)!==JSON.stringify(props.modelValue))emit('update:modelValue',ids)},{immediate:true,flush:'sync'});
function show(level:number){opened.value=level;search.value=''}
function choose(t?:Talent){const ids=props.modelValue.filter(id=>props.talents.find(v=>v.id===id)?.level!==opened.value);if(t)ids.push(t.id);emit('update:modelValue',ids);opened.value=0}
</script>
<template><section class="talent-slots"><h3>仙命</h3><div class="fate-grid"><button v-for="(label,i) in names" :key="i" type="button" @click="show(i+1)"><small>{{label}}</small><strong>{{slots[i]?.name??(i===0?'请先选择角色':'选择仙命')}}</strong><span v-if="slots[i]&&!slots[i]?.supported">{{slots[i]?.isBattleTalent===false?'局外仙命':'暂未支持模拟'}}</span></button></div><h3>已有状态</h3><div class="state-placeholder" aria-label="已有状态（暂未实现）"></div>
<Teleport to="body"><div v-if="opened" class="fate-overlay"><section class="fate-dialog" role="dialog" aria-modal="true" :aria-label="`${names[opened-1]}仙命选择`"><header><h2>{{names[opened-1]}}仙命</h2><button type="button" @click="opened=0">关闭</button></header><template v-if="opened===1"><p>炼气仙命由角色决定。</p><h3>{{initial?.name??'请先在人物属性中选择角色'}}</h3><p>{{initial?.description||initial?.supportReason}}</p></template><template v-else><input v-model="search" placeholder="搜索仙命名称或ID"><button type="button" @click="choose()">清空此格</button><div class="fate-options"><button v-for="t in candidates" :key="t.id" type="button" :disabled="t.supported===false&&t.isBattleTalent!==false" @click="choose(t)"><strong>{{t.name}}</strong><p>{{t.description||t.supportReason}}</p><small>{{t.supported?'':t.isBattleTalent===false?'局外效果，不参与战斗结算':'暂未支持战斗模拟'}}</small></button></div><p v-if="!candidates.length">当前角色在此境界没有匹配的候选。</p></template></section></div></Teleport></section></template>
<style scoped>.fate-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.fate-grid button{padding:14px 6px;min-height:100px;border:1px solid #a7997a;border-radius:8px;background:#f7f1e3;color:#304a40;cursor:pointer}.fate-grid small,.fate-grid strong,.fate-grid span{display:block}.fate-grid small{margin-bottom:12px}.fate-grid span{font-size:11px;margin-top:8px}.state-placeholder{height:55px;border:1px dashed #c4bca9;border-radius:6px}.fate-overlay{position:fixed;inset:0;z-index:1200;display:grid;place-items:center;background:#17251fbb}.fate-dialog{width:min(850px,92vw);max-height:85vh;overflow:auto;padding:24px;background:#f5f0e4;border-radius:12px;color:#283c32}.fate-dialog header{display:flex;justify-content:space-between;align-items:center}.fate-dialog button,.fate-dialog input{padding:10px;border:1px solid #b6a88c;border-radius:6px}.fate-options{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px;margin-top:15px}.fate-options button{text-align:left;background:#fffaf0;cursor:pointer}.fate-options button:disabled{opacity:.5;cursor:not-allowed}.fate-options p{font-size:13px;white-space:pre-line}.fate-options small{color:#87724e}</style>

